# Define optimized CUDA kernel with 2D register tiling
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 16
#define TILE_SIZE 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = by * BLOCK_SIZE * TILE_SIZE + ty * TILE_SIZE;
    int col = bx * BLOCK_SIZE * TILE_SIZE + tx * TILE_SIZE;

    float c[TILE_SIZE][TILE_SIZE] = {{0.0f}};

    int numTiles = (N + BLOCK_SIZE - 1) / BLOCK_SIZE;

    for (int t = 0; t < numTiles; t++) {
        // Load tiles into shared memory
        for (int i = 0; i < TILE_SIZE; i++) {
            int A_row = row + i;
            int A_col = t * BLOCK_SIZE + tx;

            if (A_row < N && A_col < N) {
                As[ty * TILE_SIZE + i][tx] = A[A_row * N + A_col];
            } else {
                As[ty * TILE_SIZE + i][tx] = 0.0f;
            }

            int B_row = t * BLOCK_SIZE + ty;
            int B_col = col + i;

            if (B_row < N && B_col < N) {
                Bs[ty][tx * TILE_SIZE + i] = B[B_row * N + B_col];
            } else {
                Bs[ty][tx * TILE_SIZE + i] = 0.0f;
            }
        }

        __syncthreads();

        // Compute partial product with 2D register tiling
        for (int k = 0; k < BLOCK_SIZE; k++) {
            float a[TILE_SIZE];
            float b[TILE_SIZE];

            for (int i = 0; i < TILE_SIZE; i++) {
                a[i] = As[ty * TILE_SIZE + i][k];
                b[i] = Bs[k][tx * TILE_SIZE + i];
            }

            for (int i = 0; i < TILE_SIZE; i++) {
                for (int j = 0; j < TILE_SIZE; j++) {
                    c[i][j] += a[i] * b[j];
                }
            }
        }

        __syncthreads();
    }

    // Write result
    for (int i = 0; i < TILE_SIZE; i++) {
        for (int j = 0; j < TILE_SIZE; j++) {
            if (row + i < N && col + j < N) {
                C[(row + i) * N + (col + j)] = c[i][j];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 threadsPerBlock(BLOCK_SIZE, BLOCK_SIZE);
    dim3 numBlocks((N + BLOCK_SIZE * TILE_SIZE - 1) / (BLOCK_SIZE * TILE_SIZE), 
                   (N + BLOCK_SIZE * TILE_SIZE - 1) / (BLOCK_SIZE * TILE_SIZE));

    matmul_kernel<<<numBlocks, threadsPerBlock>>>(A.data_ptr<float>(), 
                                                 B.data_ptr<float>(), 
                                                 C.data_ptr<float>(), 
                                                 N);

    return C;
}
